import sys, json
class Solution:
    def countSegments(self, s):
        ans = 0
        in_segment = False
        for ch in s:
            if ch != ' ':
                if not in_segment:
                    ans += 1
                    in_segment = True
            else:
                in_segment = False
        return ans

